import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.CxkNbRKf.js";const u=JSON.parse('{"title":"API logs","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/api-logs.md","filePath":"admin-guide/web-ui/api-logs.md","lastUpdated":1786379412000}'),r={name:"admin-guide/web-ui/api-logs.md"};function i(d,e,n,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="api-logs" tabindex="-1">API logs <a class="header-anchor" href="#api-logs" aria-label="Permalink to &quot;API logs&quot;">​</a></h1><p>The API logs page provides an audit trail of all API requests made to NADA. Use it to monitor API usage, troubleshoot integration issues, and review authorization failures.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: API logs list view with columns for timestamp, method, URI, response code, and authorized status</em></p></div><h2 id="accessing-api-logs" tabindex="-1">Accessing API logs <a class="header-anchor" href="#accessing-api-logs" aria-label="Permalink to &quot;Accessing API logs&quot;">​</a></h2><p>Go to <strong>Reports → API logs</strong> in the administrator menu.</p><h2 id="log-fields" tabindex="-1">Log fields <a class="header-anchor" href="#log-fields" aria-label="Permalink to &quot;Log fields&quot;">​</a></h2><p>Each log entry records:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Timestamp</td><td>Date and time of the request</td></tr><tr><td>Method</td><td>HTTP method: GET, POST, PUT, DELETE, or PATCH</td></tr><tr><td>URI</td><td>The API endpoint called</td></tr><tr><td>Response code</td><td>HTTP status code returned</td></tr><tr><td>Response time</td><td>Time taken to process the request</td></tr><tr><td>Authorized</td><td>Whether the request was authenticated</td></tr><tr><td>IP address</td><td>Client IP address</td></tr><tr><td>User ID</td><td>Authenticated user, if any</td></tr><tr><td>API key</td><td>First 10 characters of the key used</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: API log entry detail view showing all fields</em></p></div><h2 id="searching-and-filtering" tabindex="-1">Searching and filtering <a class="header-anchor" href="#searching-and-filtering" aria-label="Permalink to &quot;Searching and filtering&quot;">​</a></h2><p>Use the search box to find entries by keyword across all fields, or select a specific field to target (URI, Method, API Key, IP Address, Authorized, Response Code, User ID).</p><p>Filter by date range using the <strong>From</strong> and <strong>To</strong> date pickers.</p><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><p>Click any column header to sort by that field. The default sort is by timestamp, most recent first.</p><h2 id="log-volume" tabindex="-1">Log volume <a class="header-anchor" href="#log-volume" aria-label="Permalink to &quot;Log volume&quot;">​</a></h2><p>When the API logs table grows large, the page shows a warning with the current row count. Use the <strong>Cleanup</strong> link to archive or delete old entries and maintain query performance.</p><h2 id="common-use-cases" tabindex="-1">Common use cases <a class="header-anchor" href="#common-use-cases" aria-label="Permalink to &quot;Common use cases&quot;">​</a></h2><ul><li><strong>Troubleshoot a failed integration</strong> — filter by the client&#39;s IP or API key and look for non-2xx response codes</li><li><strong>Audit API key usage</strong> — search by API key to see all requests made with that key</li><li><strong>Identify unauthorized access attempts</strong> — filter by Authorized = No</li></ul>',18)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
